<?php

declare(strict_types=1);
$adminActiveModule = 'meu-financeiro';
$formatMoney = static fn(mixed $amount): string => 'R$ ' . number_format((float) $amount, 2, ',', '.');
$eligibleStatuses = ['pendente', 'parcial', 'postergado', 'negociado'];
$pendingNegotiations = [];
foreach ($account['negotiations'] as $negotiation) {
    if ($negotiation['status'] === 'aguardando') $pendingNegotiations[(int) $negotiation['obrigacao_id']] = $negotiation;
}
$ownBalance = 0.0;
foreach ($account['obligations'] as $ownObligation) {
    if (in_array($ownObligation['status'], $eligibleStatuses, true)) {
        $ownBalance += max(0, (float) ($ownObligation['valor_negociado'] ?? $ownObligation['valor_original']) - (float) $ownObligation['pago']);
    }
}
?>
