            <?php if ($account['obligations'] === []): ?><p class="finance-empty">Você não tem cobranças registradas.</p><?php else: ?><div class="finance-obligation-list"><?php foreach ($account['obligations'] as $obligation): $total = (float) ($obligation['valor_negociado'] ?? $obligation['valor_original']); $balance = max(0, $total - (float) $obligation['pago']); $awaiting = \Modules\Financeiro\Models\FinanceModel::truthy($obligation['pagamento_aguardando']); $canPay = in_array($obligation['status'], $eligibleStatuses, true) && $balance > 0 && !$awaiting; $referenceTitle = str_starts_with((string) $obligation['referencia'], 'evento:') ? 'Contribuição por jogo' : 'Contribuição mensal'; ?><article class="finance-obligation"><div class="finance-obligation-main"><h3><?= $escape($obligation['evento_titulo'] ?: $referenceTitle) ?></h3><p>Vencimento <?= $escape((new DateTimeImmutable((string) $obligation['vencimento']))->format('d/m/Y')) ?></p><span class="finance-status is-<?= $escape($obligation['status']) ?>"><?= $escape(ucfirst($obligation['status'])) ?></span><?php if ($obligation['motivo_status']): ?><small><?= $escape($obligation['motivo_status']) ?></small><?php endif; ?></div><div class="finance-obligation-amount"><span>Valor <?= $formatMoney($total) ?></span><span>Pago <?= $formatMoney($obligation['pago']) ?></span><strong>Saldo <?= $formatMoney($balance) ?></strong><?php if ($awaiting): ?><span class="finance-pending-note">Pagamento enviado e aguardando conferência.</span><?php endif; ?></div>
                    <?php if ($canPay): ?><form class="finance-payment-form app-form" method="post" action="meu-financeiro"><h4>Regularizar esta cobrança</h4><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="action" value="submit-payment"><input type="hidden" name="obligation_id" value="<?= (int) $obligation['id'] ?>"><div class="finance-payment-fields"><label>Valor pago<input type="number" name="amount" min="0.01" max="<?= number_format($balance, 2, '.', '') ?>" step="0.01" required></label><label>Data do pagamento<input type="date" name="payment_date" value="<?= date('Y-m-d') ?>" required></label><label>Observação / referência do Pix<input name="description" maxlength="240" placeholder="Opcional"></label><button class="app-button" type="submit">Informar pagamento</button></div></form>
                        <?php if (isset($pendingNegotiations[(int) $obligation['id']])): ?><p class="finance-pending-note" role="status">Sua proposta de negociação está aguardando análise.</p><?php else: ?><form class="finance-payment-form app-form" method="post" action="meu-financeiro"><h4>Propor negociação</h4><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="action" value="request-negotiation"><input type="hidden" name="obligation_id" value="<?= (int) $obligation['id'] ?>"><div class="finance-payment-fields"><label>Novo valor total proposto<input type="number" name="proposed_amount" min="0.01" max="<?= number_format($total, 2, '.', '') ?>" step="0.01" required></label><label class="finance-negotiation-message">Explique sua proposta<input name="message" maxlength="240" placeholder="Opcional"></label><button class="app-button app-button-outline" type="submit">Enviar proposta</button></div></form><?php endif; ?>
                    <?php endif; ?>
                </article><?php endforeach; ?></div><?php endif; ?>
        </section>
        <?php if ($account['payments'] !== []): ?><section class="finance-panel" aria-labelledby="account-payments-title"><div class="finance-panel-heading"><div><p class="finance-kicker">ACOMPANHAMENTO</p><h2 id="account-payments-title">Pagamentos informados</h2></div></div><div class="finance-table-wrap"><table class="finance-table"><caption>Seus pagamentos e situação da conferência</caption><thead><tr><th>Referência</th><th>Valor</th><th>Data informada</th><th>Situação</th></tr></thead><tbody><?php foreach ($account['payments'] as $payment): ?><tr><td><?= $escape($payment['evento_titulo'] ?: $payment['referencia']) ?></td><td><?= $formatMoney($payment['valor']) ?></td><td><?= $escape((new DateTimeImmutable((string) $payment['data_pagamento']))->format('d/m/Y')) ?></td><td><span class="finance-status is-<?= $escape($payment['status']) ?>"><?= $payment['status'] === 'aguardando' ? 'Em conferência' : ($payment['status'] === 'confirmado' ? 'Confirmado' : 'Recusado') ?></span></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
        <?php if ($account['negotiations'] !== []): ?><section class="finance-panel" aria-labelledby="account-negotiations-title"><div class="finance-panel-heading"><div><p class="finance-kicker">ACORDOS</p><h2 id="account-negotiations-title">Propostas de negociação</h2></div></div><div class="finance-table-wrap"><table class="finance-table"><caption>Suas propostas e respostas do financeiro</caption><thead><tr><th>Referência</th><th>Valor proposto</th><th>Situação</th><th>Resposta</th></tr></thead><tbody><?php foreach ($account['negotiations'] as $negotiation): ?><tr><td><?= $escape($negotiation['evento_titulo'] ?: $negotiation['referencia']) ?></td><td><?= $formatMoney($negotiation['valor_proposto']) ?></td><td><span class="finance-status is-<?= $escape($negotiation['status']) ?>"><?= $negotiation['status'] === 'aguardando' ? 'Aguardando análise' : ($negotiation['status'] === 'aceita' ? 'Aceita' : 'Recusada') ?></span></td><td><?= $escape($negotiation['resposta'] ?: '—') ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
